","checked_at":"2026-11-17","locator":"Introducción y WINTERPAUSE"}],"source_url":"https://www.museumaargau.ch/schloss-hallwyl","source_title":"Aargau · Castillo de Hallwyl","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","needs_periodic_review":false,"next_review_at":"2027-11-17","concept_id":"AG:hallwyl-tipo","status":"published","editorial_difficulty":"facil","correct_index":1,"editorial_review":{"date":"2026-11-18","revision":"complete-14","kind":"wording-and-interaction"}},"known":["d385560ad80dd352305ef0c7195460b1"]},{"question":{"id":"szx-ag-habsburg-familia","collection":"suizamente-integration-1350-v1","territory":"AG","scope":"canton","canton":"AG","topic":"cultura","category":"sociedad","difficulty":3,"language":"es","game_type":"choice","prompt":"¿Qué dinastía da nombre al castillo de Habsburg?","options":["Los Tudor","Los Borbones","Los Habsburgo","Los Romanov"],"explanation":"El museo explica los orígenes y el ascenso de esa familia. No hace falta memorizar una fecha para reconocer la conexión.","sources":[{"id":"ag-habsburg-17","url":"https://www.museumaargau.ch/schloss-habsburg","title":"Aargau · Origen de los Habsburgo","authority":"Museum Aargau","checked_at":"2026-11-17","locator":"Introducción, Stammschloss"}],"source_url":"https://www.museumaargau.ch/schloss-habsburg","source_title":"Aargau · Origen de los Habsburgo","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","needs_periodic_review":false,"next_review_at":"2027-11-17","concept_id":"AG:habsburg-familia","status":"published","editorial_difficulty":"media","correct_index":2,"editorial_review":{"date":"2026-11-18","revision":"complete-14","kind":"wording-and-interaction"}},"known":["629d5bd0f5057449d27150b2c253b258"]},{"question":{"id":"szx-ag-wasser-que-es","collection":"suizamente-integration-1350-v1","territory":"AG","scope":"canton","canton":"AG","topic":"naturaleza","category":"sociedad","difficulty":3,"language":"es