1-17","locator":"Schon gewusst y 2000 Jahre Bädergeschichte"}],"source_url":"https://www.deinbaden.ch/de/erleben/wellbeing","source_title":"Aargau · Aguas de Baden","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","needs_periodic_review":false,"next_review_at":"2027-11-17","concept_id":"AG:baden-agua","status":"published","editorial_difficulty":"facil","correct_index":0,"editorial_review":{"date":"2026-11-18","revision":"complete-14","kind":"wording-and-interaction"}},"known":["ce394c1d882522a8e645680fe56177c0"]},{"question":{"id":"szx-ag-aia-orientacion","collection":"suizamente-integration-1350-v1","territory":"AG","scope":"canton","canton":"AG","topic":"tramites","category":"administracion","difficulty":1,"language":"es","game_type":"choice","prompt":"Te instalas en Aargau y necesitas orientación para encontrar un curso y entender los servicios locales. ¿Qué recurso señala Hallo Aargau?","options":["El registro de castillos","Anlaufstelle Integration Aargau, AIA","El control de equipajes del museo","El servicio de venta de entradas"],"explanation":"AIA orienta y ayuda a encontrar recursos especializados; no concede por eso permisos o prestaciones.","sources":[{"id":"ag-advice-17","url":"https://www.hallo-aargau.ch/de/notfaelle-und-beratungsstellen/beratungsstellen","title":"Aargau · Orientación AIA","authority":"Kanton Aargau, Hallo Aargau","checked_at":"2026-11-17","locator":"Allgemeine Beratungsstellen"}],"source_url":"https://www.hallo-aargau.ch/de/notfaelle-und-beratungsstellen/beratungsstellen","source_title":"Aargau · Orientación AIA","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","needs_periodic_review":true,"next_review_at":"2027-02-17","concept_id":"AG:aia-orientacion","status":"published","editorial_difficulty":"facil","correct_index":1},"known":["8c456a3f7d116297eafc01f268890878"]},{"question":{"id":"szx-ag-ipv-2027-fecha","collection":"suizamente-integration-1350-v1","territory"