https://www.auenstein.ch/gemeinde-aktuelles/informationen/aktuelles.html/89/news/3466","title":"Aargau · Solicitud de primas 2027","authority":"Gemeinde Auenstein, información de SVA Aargau","checked_at":"2026-11-17","locator":"Comunicado 29 octubre 2026, solicitud y cambios"}],"source_url":"https://www.auenstein.ch/gemeinde-aktuelles/informationen/aktuelles.html/89/news/3466","source_title":"Aargau · Solicitud de primas 2027","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","needs_periodic_review":true,"next_review_at":"2026-12-31","concept_id":"AG:ipv-sin-codigo","status":"published","validity_year":2027,"editorial_difficulty":"media","correct_index":3,"editorial_review":{"date":"2026-11-18","revision":"complete-14","kind":"wording-and-interaction"}},"known":["6aebe0701a66e3a41f46e569ae7e1885"]},{"question":{"id":"szx-ag-perro-borde-junio","collection":"suizamente-integration-1350-v1","territory":"AG","scope":"canton","canton":"AG","topic":"derechos","category":"administracion","difficulty":3,"language":"es","game_type":"choice","prompt":"En junio paseas con tu perro de compañía por el borde de un bosque de Aargau. ¿Qué regla estacional publica el cantón?","options":["Llevarlo con correa","Soltarlo si no ves otras personas","Atarlo solo dentro de un municipio grande","Aplicar únicamente el horario del museo"],"explanation":"La regla del 1 de abril al 31 de julio comprende bosque y borde. No se pregunta por una excepción oficial de trabajo.","sources":[{"id":"ag-dogs-17","url":"https://www.ag.ch/de/themen/landwirtschaft-tiere/heim-und-nutztiere/hunde","title":"Aargau · Perros y convivencia","authority":"Kanton Aargau, Veterinärdienst","checked_at":"2026-11-17","locator":"Hunde: obligaciones y Leinenpflicht"}],"source_url":"https://www.ag.ch/de/themen/landwirtschaft-tiere/heim-und-nutztiere/hunde","source_title":"Aargau · Perros y convivencia","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","ne